const D={noMatch:['No matching record in the sample registry. This is not proof of fraud.','नमूना रजिस्ट्री में मिलता रिकॉर्ड नहीं है। यह धोखाधड़ी का प्रमाण नहीं है।'],categoryMismatch:['Claimed activity differs from the sample registration category.','दिया गया काम नमूना पंजीकरण की श्रेणी से अलग है।'],strong:['Strong warning','गंभीर चेतावनी'],verify:['Needs verification','जाँच ज़रूरी है'],limited:['No identified warning in available evidence','उपलब्ध सबूत में चेतावनी नहीं मिली'],supported:['Supported by evidence','सबूत से समर्थित'],mismatch:['Mismatch','अंतर मिला'],unverified:['Unverified','जाँच बाकी है'],registration:['Registration record','पंजीकरण रिकॉर्ड'],name:['Entity name','संस्था का नाम'],association:['Sender / domain / handle','भेजने वाला / वेबसाइट / हैंडल'],offer:['Exact offer','यह विशेष प्रस्ताव'],payment:['Payment demand','भुगतान की माँग'],approach:['Approach','संपर्क'],identity:['Identity claim','पहचान का दावा'],portal:['Portal / app invitation','वेबसाइट / ऐप निमंत्रण'],gains:['Claimed gains','लाभ का दावा'],barrier:['Withdrawal barrier','निकासी में बाधा'],record:['Example record found. This says nothing about the sender.','नमूना रिकॉर्ड मिला। इससे भेजने वाले की पहचान साबित नहीं होती।'],lookup:['No live registry connection. Use the official manual route.','लाइव रजिस्ट्री जुड़ी नहीं है। आधिकारिक जाँच का रास्ता उपयोग करें।'],nameMatch:['Exact name matches the sample record.','नाम नमूना रिकॉर्ड से ठीक मेल खाता है।'],nameMismatch:['Claimed name differs from the sample record.','दिया गया नाम नमूना रिकॉर्ड से अलग है।'],nameMissing:['No exact entity name supplied.','संस्था का सही नाम नहीं दिया गया।'],domainMismatch:['The supplied identifier differs from the sample official reference.','दिया गया पहचानकर्ता नमूना आधिकारिक संदर्भ से अलग है।'],association:['Sender / domain / handle','भेजने वाला / वेबसाइट / हैंडल'],offer:['Exact offer','यह विशेष प्रस्ताव'],payment:['Payment demand','भुगतान की माँग'],paymentConcern:['A payment-to-release pattern needs independent verification.','पैसे निकालने के लिए भुगतान माँगा गया है। स्वतंत्र जाँच ज़रूरी है।']};
const word=k=>D[k]?.[state.lang==='hi'?1:0]??k;
