function toast(en,hi){$('#toast').textContent=tr(en,hi??en);$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(title,body,onReady){$('#modal').innerHTML=`<button class="close" aria-label="${tr('Close','बंद करें')}">×</button><h2 id="modalTitle">${title}</h2>${body}`;$('#modal .close').onclick=()=>$('#modal').close();$('#modal').showModal();onReady?.();}
function confirmAction(title,detail,fn){modal(title,`<p>${detail}</p><div class="actions"><button id="confirm" class="btn danger">${tr('Confirm','पुष्टि करें')}</button><button id="cancel" class="btn">${tr('Cancel','रद्द करें')}</button></div>`,()=>{$('#cancel').onclick=()=>$('#modal').close();$('#confirm').onclick=async()=>{await fn();$('#modal').close()}})}
const languageIcon='<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg>';
const micIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg>';
