function headings(h,p){return `<div class="topline"><div><div class="eyebrow">${tr('CHECK BEFORE PAYING','भुगतान से पहले जाँचें')}</div><h1>${h}</h1><p class="muted">${p}</p></div><span class="local">${lock}${tr('On this device','इसी डिवाइस पर')}</span></div>`}
function external(url,label){return `<a class="btn small" href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`}
const result=c=>analyze(c.events,{fixture:c.fixture,sourceMode:c.sourceMode,lang:state.lang});
function notifyUpdate(){window.dispatchEvent(new Event('nr-change'))}
async function persist(){try{if(state.save)await saveVault({schema:1,cases:state.cases,settings:{retention:state.retention,save:true}});notifyUpdate()}catch{state.save=false;toast('Storage failed. Cases remain in this session only.','संग्रह नहीं हो सका। मामले इस सत्र में ही रहेंगे।')}}
function prune(){const t=Date.now()-state.retention*86400000;state.cases=state.cases.filter(c=>new Date(c.updatedAt).getTime()>t)}
function render(){cancelML();voiceInput?.cancel();window.speechSynthesis?.cancel();prune();document.documentElement.lang=state.lang;$('#brandSub').textContent=tr('Investment identity guard','निवेश पहचान जाँच');$('#navCheck').textContent=tr('Check an offer','प्रस्ताव जाँचें');$('#navCases').textContent=tr('My cases','मेरे मामले');$('#navSettings').textContent=tr('Settings','सेटिंग्स');if($('#navLearn'))$('#navLearn').textContent=tr('Learn & stay safe','सीखें और सुरक्षित रहें');if($('#navResources'))$('#navResources').textContent=tr('Resources','संसाधन');if($('#navSaved'))$('#navSaved').textContent=tr('Saved','सहेजे गए');if($('#navAlerts'))$('#navAlerts').textContent=tr('Scam alerts','धोखे की चेतावनी');if($('#sidebarCta'))$('#sidebarCta').innerHTML=tr('Learn how it works','जानें कैसे काम करता है')+' <b>→</b>';$('#language').innerHTML=languageIcon;$('#language').setAttribute('aria-label',tr('Switch to Hindi','Switch to English'));$('#language').title=tr('Switch to Hindi','Switch to English');$('#foot').textContent=tr('Local analysis. No investment advice. No safety guarantee.','स्थानीय जाँच। निवेश सलाह नहीं। सुरक्षा की गारंटी नहीं।');if($('.sidebarNote strong'))$('.sidebarNote strong').innerHTML=tr('Spot scams.<br>Invest smarter.','धोखे पहचानें।<br>समझदारी से निवेश करें।');if($('.sidebarNote span'))$('.sidebarNote span').textContent=tr('Clear explanations to help you check before paying.','भुगतान से पहले जाँच के लिए सरल जानकारी।');$('#coverage').textContent=tr('What this prototype covers','प्रोटोटाइप में क्या है');$$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view||state.view==='result'&&b.dataset.view==='cases');b.setAttribute('aria-current',b.classList.contains('active')?'page':'false')});$('#main').innerHTML=state.view==='check'?checkView():['cases','saved','alerts'].includes(state.view)?casesView():state.view==='settings'?settingsView():caseView();bind();if(state.view==='settings'&&native)nativeSettings();}
function openGuide(kind){modal(kind==='resources'?tr('Official resources','आधिकारिक संसाधन'):tr('Learn & stay safe','सीखें और सुरक्षित रहें'),`<div class="steps">${[tr('A genuine registration number does not prove that the sender represents the institution.','असली पंजीकरण संख्या से भेजने वाले का संस्था से संबंध साबित नहीं होता।'),tr('Check the exact website address. A familiar name inside a different domain is not proof of ownership.','वेबसाइट का पूरा पता जाँचें। अलग डोमेन में जाना-पहचाना नाम मालिकाना हक का सबूत नहीं है।'),tr('Pause if asked to pay more to unlock a withdrawal. Verify the demand through an independent official contact.','निकासी खोलने के लिए और पैसे माँगे जाएँ तो रुकें। स्वतंत्र आधिकारिक संपर्क से माँग की पुष्टि करें।')].map((x,i)=>`<div class="guideStep"><b>${i+1}</b><span>${x}</span></div>`).join('')}</div><div class="actions spacing">${external(SOURCES.support,tr('SEBI investor resources','SEBI निवेशक संसाधन'))}${external(SOURCES.payment,tr('SEBI Check','SEBI Check'))}</div><p class="hint">${tr('External sites open only when you choose. No message is sent automatically.','बाहरी साइट आपके चुनने पर खुलती है। संदेश अपने आप नहीं भेजा जाता।')}</p>`)}
function verificationNotice(){return `<p class="hint verificationNotice">${tr('Live official verification is pending. Demo registry records are fictional; real offers require independent verification.','लाइव आधिकारिक सत्यापन अभी उपलब्ध नहीं है। नमूना रजिस्ट्री रिकॉर्ड काल्पनिक हैं; वास्तविक प्रस्तावों की स्वतंत्र जाँच ज़रूरी है।')}</p>`}
function checkView(){return `<section class="welcome"><div class="dashboardToolbar"><label class="searchBox"><span aria-hidden="true">⌕</span><input id="dashboardSearch" type="search" aria-label="${tr('Search your cases','अपने मामले खोजें')}" placeholder="${tr('Search past cases, company names, URLs…','मामले, कंपनी के नाम, लिंक खोजें…')}"><kbd>↵</kbd></label><button class="toolbarLang" id="topLanguage" aria-label="${tr('Switch to Hindi','Switch to English')}" title="${tr('Switch to Hindi','Switch to English')}">${languageIcon}</button><button id="aboutProfile" class="profileMark" aria-label="${tr('Manage your account','अपना खाता प्रबंधित करें')}">N</button></div><div class="dashboardHero"><div class="welcomeIntro"><div class="eyebrow">${tr('INVESTMENT SAFETY ANALYSIS','निवेश सुरक्षा जाँच')}</div><h1>${tr('Check before<br>you <em>invest.</em>','निवेश से पहले<br><em>जाँच करें।</em>')}</h1><p class="muted">${tr('Spot warning signs. Understand the claims.<br>Take your next step with clarity.','चेतावनी संकेत पहचानें। दावे समझें।<br>अगला कदम सोच-समझकर लें।')}</p></div><div class="simpleFlow" aria-label="${tr('How it works','कैसे काम करता है')}"><span><b>⌕</b> ${tr('Detect risky patterns','जोखिम संकेत पहचानें')}</span><span><b>▤</b> ${tr('Review identity claims','पहचान के दावे देखें')}</span><span><b>♧</b> ${tr('Connect the evidence','सबूत जोड़ें')}</span><span><b>♢</b> ${tr('Get clear explanations','सरल कारण समझें')}</span></div></div><div class="dashboardGrid"><div class="dashboardPrimary"><div class="paper intakeCard"><div class="inputTabs" role="tablist" aria-label="${tr('Input type','इनपुट प्रकार')}">${['message','link','screenshot'].map(t=>`<button role="tab" aria-selected="${state.inputType===t}" class="${state.inputType===t?'active':''}" data-input="${t}">${t==='message'?tr('Message','संदेश'):t==='link'?tr('Link','लिंक'):tr('Screenshot','स्क्रीनशॉट')}</button>`).join('')}</div>${state.inputType==='screenshot'?`<label for="image">${tr('Choose one screenshot','एक स्क्रीनशॉट चुनें')}</label><input id="image" type="file" accept="image/png,image/jpeg,image/webp"><div id="imagePreview"></div><p class="notice blue">${tr('Choose a screenshot. We read its Hindi/English text automatically on your device; no typing needed.','स्क्रीनशॉट चुनें। हिन्दी/अंग्रेज़ी पाठ इसी डिवाइस पर अपने आप पढ़ा जाएगा; लिखने की ज़रूरत नहीं।')}</p>`:''}${state.inputType==='link'?`<p class="hint">${tr('Paste a public HTTPS link. When you check it, our server reads the public page; no extra message is needed. Private or login-only pages cannot be read.','सार्वजनिक HTTPS लिंक डालें। जाँच पर सर्वर उसका पाठ पढ़ेगा; अलग संदेश की ज़रूरत नहीं। निजी या लॉगिन वाले पेज नहीं पढ़ सकते।')}</p>`:''}<label for="input">${state.inputType==='link'?tr('Investment link or social handle','निवेश लिंक या सोशल हैंडल'):tr('Message to check','जाँचने वाला संदेश')}</label><div class="dictationBox"><textarea id="input" maxlength="10000" placeholder="${tr('Paste the message, claim or investment link here…','संदेश, दावा या निवेश लिंक यहाँ डालें…')}">${esc(state.input)}</textarea><div class="dictationToolbar"><span id="voiceHint">${tr('Type or tap the microphone','लिखें या माइक दबाएँ')}</span><label class="srOnly" for="voiceLanguage">${tr('Speaking language','बोलने की भाषा')}</label><select id="voiceLanguage" aria-label="${tr('Speaking language','बोलने की भाषा')}"><option value="en-IN" ${state.lang==='en'?'selected':''}>English</option><option value="hi-IN" ${state.lang==='hi'?'selected':''}>हिन्दी</option></select><button type="button" class="micButton" id="voiceStart" aria-label="${tr('Start voice typing','बोलकर लिखना शुरू करें')}" title="${tr('Start voice typing','बोलकर लिखना शुरू करें')}" aria-pressed="false">${micIcon}</button></div></div><p id="voiceStatus" class="hint voiceStatus" role="status" aria-live="polite"></p><p class="voicePrivacy">${tr('Microphone audio may be processed by your browser’s speech service. Review the text before checking.','माइक की आवाज़ ब्राउज़र की वॉइस सेवा प्रोसेस कर सकती है। जाँचने से पहले पाठ देखें।')}</p>${state.synthetic?`<p class="notice blue">${tr('DEMO EXAMPLE · Fictional organisation and sample registry. Not a live official check. Editing this text switches to real-input mode.','नमूना · काल्पनिक संस्था और नमूना रजिस्ट्री। यह लाइव आधिकारिक जाँच नहीं है। पाठ बदलने पर सामान्य इनपुट मोड होगा।')}</p>`:''}<p class="hint">${tr('Keep OTPs, passwords and account details out of your message.','OTP, पासवर्ड और खाता विवरण यहाँ न डालें।')}</p><button class="uploadShortcut" id="uploadShortcut"><span aria-hidden="true">▧</span><span>${tr('Add an image or screenshot','तस्वीर या स्क्रीनशॉट जोड़ें')}<small>PNG, JPG, WEBP · ${tr('up to 5 MB','अधिकतम 5 MB')}</small></span></button><p class="hint">${tr("The first check downloads about 250 MB for on-device analysis. Wi-Fi recommended.","पहली जाँच में इसी डिवाइस पर विश्लेषण के लिए लगभग 250 MB डाउनलोड होगा। Wi-Fi बेहतर है।")}</p><div id="inputError" class="error" role="alert"></div><div class="actions"><button class="btn primary" id="analyze" ${state.paused?'disabled':''}>${tr('Check this offer','यह प्रस्ताव जाँचें')}</button><button class="textbtn" id="clearInput">${tr('Clear text','पाठ हटाएँ')}</button></div>${state.paused?`<p class="notice">${tr('Processing is paused. Resume in Privacy.','जाँच रुकी है। गोपनीयता में फिर शुरू करें।')}</p>`:''}</div>${verificationNotice()}<p class="privateLine">${lock}${tr('Message and screenshot analysis runs on your device. Links are read by our server; voice may use your browser’s speech service.','पाठ की जाँच और वैकल्पिक ML इसी ब्राउज़र में चलते हैं। आवाज़ की पहचान ब्राउज़र की क्लाउड सेवा उपयोग कर सकती है।')}</p>${state.cases.length?`<div class="recent paper"><div class="sectionhead"><h2>${tr('Recent cases','हाल के मामले')}</h2><button class="textbtn" data-view="cases">${tr('View all','सभी देखें')}</button></div>${state.cases.slice(0,3).map(caseRow).join('')}</div>`:`<div class="recent paper"><h2>${tr('Your checks, in one place','आपकी जाँच, एक जगह')}</h2><p class="muted">${tr('Your first result will appear here after you check an offer.','प्रस्ताव जाँचने के बाद आपका पहला परिणाम यहाँ दिखाई देगा।')}</p></div>`}</div><div class="dashboardSecondary"><details class="disclosure sampleDrawer"><summary>${tr('Not sure? Try an example','समझना चाहते हैं? नमूना देखें')}<div class="miniPhone" aria-hidden="true"><span>DEMO MESSAGE</span><b>Guaranteed<br>30% returns!</b><i>!</i></div></summary><p class="hint">${tr('Fictional examples. No personal information needed.','काल्पनिक नमूने। निजी जानकारी की ज़रूरत नहीं।')}</p><div class="sampleChoices">${[['identity',tr('Copied registration','कॉपी किया पंजीकरण')],['fee',tr('Withdrawal fee demand','निकासी शुल्क की माँग')],['benign',tr('Education message','शिक्षा का संदेश')],['offline',tr('Missing official source','आधिकारिक स्रोत उपलब्ध नहीं')]].map(([id,label])=>`<button class="btn small" data-sample="${id}">${label}</button>`).join('')}</div></details><aside class="howCard paper"><h2>${tr('How it works','कैसे काम करता है')}</h2><p class="muted">${tr('Three steps. One clearer decision.','तीन कदम। एक स्पष्ट फैसला।')}</p>${[tr('Paste a message or link, or select a screenshot.','संदेश या लिंक डालें, या स्क्रीनशॉट चुनें।'),tr('Review warning signals and what remains unverified.','चेतावनी संकेत और बाकी जाँच देखें।'),tr('Verify independently before sending money.','पैसे भेजने से पहले स्वतंत्र जाँच करें।')].map((x,i)=>`<div class="guideStep"><b>${i+1}</b><span>${x}</span></div>`).join('')}</aside><aside class="learnCard paper"><h2>${tr('Stay informed. Stay safe.','जानकार रहें। सतर्क रहें।')}</h2><p>${tr('Learn common scam tactics and simple verification steps.','आम धोखे और सरल जाँच के कदम समझें।')}</p><button class="btn primary small" data-guide="learn">${tr('Explore guide','गाइड देखें')} →</button><div class="bookArt" aria-hidden="true">▰<br>▰<br>▰</div></aside><aside class="impactCard paper"><h2>${tr('Your checking activity','आपकी जाँच गतिविधि')}</h2><p class="hint">${tr('This browser only · not prevention statistics','केवल इस ब्राउज़र में · धोखा रोकने के आँकड़े नहीं')}</p><div class="activityTiles"><div><b>${state.cases.length}</b><span>${tr('Offers checked','प्रस्ताव जाँचे')}</span></div><div><b>${state.cases.filter(c=>result(c).band==='strong').length}</b><span>${tr('Strong warnings','गंभीर चेतावनी')}</span></div><div><b>${tr('Local','स्थानीय')}</b><span>${tr('Message analysis','संदेश जाँच')}</span></div><div><b>${tr('Pending','बाकी')}</b><span>${tr('Live verification','लाइव सत्यापन')}</span></div></div></aside></div></div></section>`}
function caseRow(c){const a=result(c);return `<button class="caseRow" data-case="${c.id}"><span><b>${esc(title(c))}</b><small>${c.events.length} ${c.events.length===1?tr('item','साक्ष्य'):tr('items','साक्ष्य')} · ${date(c.updatedAt)} ${c.synthetic?'· '+tr('Demo','नमूना'):''}</small></span><span class="tag ${a.band}">${word(a.band)}</span></button>`}
function visibleCases(){return state.cases.filter(c=>state.view==='saved'?c.bookmarked:state.view==='alerts'?result(c).band==='strong':true)}
function casesView(){return `<section>${headings(state.view==='saved'?tr('Saved cases','सहेजे मामले'):state.view==='alerts'?tr('Scam alerts','धोखे की चेतावनी'):tr('Your verification cases','आपके जाँच मामले'),tr('Keep related evidence together. You choose when messages belong to the same case.','जुड़े सबूत साथ रखें। संदेश एक मामले के हैं या नहीं, यह आप तय करते हैं।'))}<div class="actions caseFilters"><button class="btn small" data-view="cases">${tr('All cases','सभी मामले')}</button><button class="btn small" data-view="saved">${tr('Saved','सहेजे गए')}</button><button class="btn small" data-view="alerts">${tr('Scam alerts','धोखे की चेतावनी')}</button></div><div class="paper"><label for="search">${tr('Find a case','मामला खोजें')}</label><input id="search" type="search" placeholder="${tr('Search the saved excerpts','संग्रहीत पाठ खोजें')}"><div id="caseList">${visibleCases().length?visibleCases().map(caseRow).join(''):`<div class="empty"><h2>${tr('No cases in this view','इस सूची में कोई मामला नहीं')}</h2><p class="muted">${tr('Check an offer, or bookmark an existing case using Save case on its result screen. Alerts show strong warnings from your checks only.','प्रस्ताव जाँचें या परिणाम स्क्रीन में मामला सहेजें। चेतावनी में केवल आपकी जाँच के गंभीर संकेत दिखते हैं।')}</p><button class="btn primary" data-view="check">${tr('Check an offer','प्रस्ताव जाँचें')}</button></div>`}</div></div></section>`}
function caseText(c){return c.events.map(e=>e.text).join('\n')}
function scoreMarkup(info={status:'loading'}){
 const score=displayedScore(info,selected()?result(selected()).score:null);const fallback=score.source==='rules-fallback';const ready=(info.status==='ready'||fallback)&&score.value!==null;
 const reasons={uncertain:tr('There is not enough evidence for a reliable score.','भरोसेमंद स्कोर के लिए पर्याप्त संकेत नहीं मिले।'),education:tr('Educational wording makes the score unreliable. Review the message in context.','शैक्षिक भाषा के कारण स्कोर भरोसेमंद नहीं है। पूरा संदर्भ देखें।'),partial:tr('This message is too long for a complete score. Check a shorter message.','पूरा स्कोर निकालने के लिए संदेश बहुत लंबा है। छोटा संदेश जाँचें।'),ambiguous:tr('The model could not separate the possible patterns clearly enough to give a score.','मॉडल संभावित पैटर्न स्पष्ट रूप से अलग नहीं कर सका, इसलिए स्कोर नहीं दिया गया।'),invalid:tr('The model returned an incomplete result. Please retry.','मॉडल का परिणाम अधूरा है। फिर कोशिश करें।')};
 const status=fallback?tr('AI unavailable · Rules-based fallback','AI उपलब्ध नहीं · नियमों पर आधारित जाँच'):ready?tr('Calculated from the message’s meaning','संदेश के अर्थ से गणना हुई'):info.status==='loading'?tr('Analysing your message…','आपका संदेश जाँचा जा रहा है…'):info.status==='ready'?(reasons[score.reason]||tr('Score unavailable','स्कोर उपलब्ध नहीं')):info.status==='paused'?tr('Analysis is paused. Resume it in Settings.','जाँच रुकी है। सेटिंग्स में चालू करें।'):info.status==='cancelled'?tr('Analysis cancelled. No score calculated.','जाँच रद्द। स्कोर नहीं निकला।'):tr('Could not calculate a score. Retry the analysis below.','स्कोर नहीं निकल सका। नीचे फिर जाँचें।');
 return `<div class="scoreHeading"><div><b>${tr('Message concern score','संदेश का चिंता स्कोर')}</b><p class="hint" role="status">${status}</p></div><strong>${ready?score.value:'—'}${ready?'<small>/100</small>':''}</strong></div>${ready?`<meter min="0" max="100" value="${score.value}" aria-label="${fallback?tr('Rules-based concern score','नियम आधारित चिंता स्कोर'):tr('Model-derived concern score','मॉडल से निकला चिंता स्कोर')}">${score.value}/100</meter>`:''}<p class="hint">${fallback?tr('Based on detected warning rules, not AI. Not a fraud probability. A low score does not mean safe.','पहचाने गए चेतावनी नियमों पर आधारित, AI पर नहीं। धोखाधड़ी की संभावना नहीं। कम स्कोर का मतलब सुरक्षित नहीं।'):tr('Experimental model signal, not a fraud probability or safety guarantee. A low score can miss a scam.','यह प्रायोगिक मॉडल संकेत है, धोखाधड़ी की संभावना या सुरक्षा की गारंटी नहीं। कम स्कोर पर भी धोखा छूट सकता है।')}</p>${ready&&!fallback?`<details><summary>${tr('Why this score?','यह स्कोर क्यों?')}</summary><p>${tr('The strongest concerning-pattern match from the language model is multiplied by 100. No keyword-rule points are added. This model has not been validated as a financial-fraud probability estimator.','भाषा मॉडल के सबसे मजबूत चिंता वाले पैटर्न के मिलान को 100 से गुणा किया गया है। कीवर्ड नियमों के अंक नहीं जोड़े जाते। इस मॉडल को वित्तीय धोखाधड़ी की संभावना मापने के लिए सत्यापित नहीं किया गया है।')}</p><p>${esc(CATEGORIES.find(c=>c.id===score.category)?.[state.lang==='hi'?'hi':'en']||score.category)} · ${score.raw.toFixed(3)} × 100 = ${score.value}</p></details>`:''}`;
}
function scorePanel(){return `<div class="riskScore" id="modelScorePanel">${scoreMarkup()}</div>`}

function updatePrimary(info,c){
 const host=$('#primaryResult');if(!host)return;
 const a=result(c),score=modelScore(info.result),cat=CATEGORIES.find(x=>x.id===score.category);
 const failed=info.status==='error',ready=info.status==='ready';
 const heading=failed?word(a.band):ready?(score.reason==='education'?tr('Looks like an educational warning','यह जागरूकता का संदेश लगता है'):score.value>=75?tr('Warning signs found','चेतावनी संकेत मिले'):tr('Needs a closer check','और जाँच ज़रूरी है')):info.status==='loading'?tr('Checking your message…','आपका संदेश जाँचा जा रहा है…'):tr('Check not completed','जाँच पूरी नहीं हुई');
 const detail=failed?(a.findings.map(f=>f.label).join('. ')||tr('No known warning found. This does not mean the offer is safe.','कोई ज्ञात चेतावनी नहीं मिली। इसका मतलब प्रस्ताव सुरक्षित नहीं है।')):ready?(score.reason==='education'?tr('This message appears to warn about scams, rather than make an investment promise. Its sender and links are still unverified.','यह संदेश निवेश का वादा करने के बजाय धोखे से सावधान करता लगता है। भेजने वाले और लिंक की पुष्टि अभी नहीं हुई है।'):cat?.[state.lang==='hi'?'hi':'en']||tr('We could not reach a clear conclusion. Verify independently before paying.','स्पष्ट निष्कर्ष नहीं मिला। भुगतान से पहले स्वतंत्र पुष्टि करें।')):tr('Please wait before acting on this offer.','इस प्रस्ताव पर आगे बढ़ने से पहले प्रतीक्षा करें।');
 if(ready&&score.reason==='education'){const card=$('.nextCard');if(card){card.querySelector('h2').textContent=tr('Use the advice carefully','सलाह को समझकर अपनाएँ');card.querySelector('p').textContent=tr('This appears to discuss scam prevention. If it includes a link or contact, verify it independently before sharing information or money.','यह धोखे से बचाव की जानकारी लगती है। इसमें लिंक या संपर्क हो तो जानकारी या पैसे देने से पहले उसकी स्वतंत्र पुष्टि करें।');}}
 host.className='banner '+(failed?a.band:ready&&score.value>=75?'strong':'verify');
 host.innerHTML=`<div class="eyebrow">${failed?tr('Rules-based fallback','नियम आधारित जाँच'):tr('YOUR CHECK RESULT','आपकी जाँच का परिणाम')}</div><h1>${heading}</h1><p>${esc(detail)}</p>`;
}
function caseView(){const c=state.cases.find(c=>c.id===state.selected);if(!c){state.view='cases';return casesView()}const a=result(c);const reason=(a.findings.find(f=>f.rule==='fee')??a.findings.find(f=>f.severity==='strong'))?.label??a.findings[0]?.label??(a.band==='verify'?tr('Important identity checks remain unfinished.','पहचान की ज़रूरी जाँच बाकी है।'):tr('No warning pattern matched this input. Coverage is limited.','इस पाठ में चेतावनी पैटर्न नहीं मिला। जाँच का दायरा सीमित है।'));
return `<section class="resultSimple"><div class="resultTop"><button class="textbtn" data-view="check">← ${tr('Check another offer','दूसरा प्रस्ताव जाँचें')}</button>${c.synthetic?`<span class="demoLabel">${tr('Fictional demo','काल्पनिक नमूना')}</span>`:''}</div>${verificationNotice()}${c.events.some(e=>e.linkSource)?`<p class="hint">${tr('Public page text retrieved','सार्वजनिक पेज से पाठ मिला')}: ${esc(c.events.find(e=>e.linkSource).linkSource.url)} · ${date(c.events.find(e=>e.linkSource).linkSource.retrievedAt)}. ${tr('Website claims are not verified facts.','वेबसाइट के दावे सत्यापित तथ्य नहीं हैं।')}</p>`:''}<div class="banner" id="primaryResult" role="status"><h1>${tr('Checking your message…','आपका संदेश जाँचा जा रहा है…')}</h1></div>${scorePanel(a,c)}<div id="mlPanel" class="paper mlPanel"></div><div class="paper nextCard"><div class="eyebrow">${tr('WHAT TO DO NEXT','अब क्या करें')}</div><h2>${tr('Verify before you pay','भुगतान से पहले पुष्टि करें')}</h2><p>${a.next==='payment'?tr('Ask the institution through an independent official contact whether this payment recipient and withdrawal fee are authorised.','स्वतंत्र आधिकारिक संपर्क से संस्था से पूछें कि भुगतान पाने वाला और निकासी शुल्क अधिकृत हैं या नहीं।'):tr('Use an independent official contact to ask whether this sender and this exact offer belong to the institution.','स्वतंत्र आधिकारिक संपर्क से पूछें कि भेजने वाला और यह विशेष प्रस्ताव संस्था के हैं या नहीं।')}</p><button class="btn primary" id="contact">${tr('Help me verify','जाँच करने में मदद करें')} →</button><p class="hint">${tr('You choose whether to contact them. Nothing is sent automatically.','संपर्क करना आपका फैसला है। अपने आप कुछ नहीं भेजा जाता।')}</p></div><button class="btn small bookmarkBtn" id="bookmarkCase">${c.bookmarked?tr('Remove from Saved','सहेजी सूची से हटाएँ'):tr('Save case','मामला सहेजें')}</button><div class="quietActions"><button class="textbtn" id="listen">${tr('Listen to the result','परिणाम सुनें')}</button><button class="textbtn" id="addEvidence">+ ${tr('Add another message','एक और संदेश जोड़ें')}</button></div><details class="disclosure" id="checkDetails" ${state.detailsOpen?'open':''}><summary>${tr('See why — checks and evidence','कारण देखें — जाँच और सबूत')}<span class="hint">${a.mismatches} ${tr('mismatch','अंतर')} · ${a.unknown} ${tr('unverified','जाँच बाकी')}</span></summary><p class="hint">${tr('These are separate check counts, not a risk score or safety guarantee.','ये अलग जाँच की गिनती हैं, जोखिम स्कोर या सुरक्षा की गारंटी नहीं।')}</p><div class="viewTabs" role="tablist">${[['identity',tr('Checks','जाँच')],['evidence',tr('Reasons','कारण')],['timeline',tr('Messages','संदेश')],['next',tr('More help','और मदद')]].map(([k,l])=>`<button role="tab" aria-selected="${state.tab===k}" data-tab="${k}" class="${state.tab===k?'active':''}">${l}</button>`).join('')}</div>${state.tab==='identity'?identityPanel(a,c):state.tab==='evidence'?evidencePanel(a,c):state.tab==='timeline'?timelinePanel(a,c):nextPanel(a,c)}</details>${c.synthetic?`<details class="disclosure"><summary>${tr('Explore the demo further','नमूने को आगे देखें')}</summary><p class="hint">${tr('All organisation details and registry records in this demo are fictional.','इस नमूने की संस्था और रजिस्ट्री के सभी रिकॉर्ड काल्पनिक हैं।')}</p><div class="actions"><button class="btn small" id="samplePortal">${tr('Add portal invitation','वेबसाइट निमंत्रण जोड़ें')}</button><button class="btn small" id="sampleFee">${tr('Add withdrawal demand','निकासी की माँग जोड़ें')}</button></div><label for="sourceMode" class="spacing">${tr('Demo source availability','नमूना स्रोत उपलब्धता')}</label><select id="sourceMode">${[['available',tr('Available sample record','उपलब्ध नमूना रिकॉर्ड')],['stale',tr('Stale sample record','पुराना नमूना रिकॉर्ड')],['unavailable',tr('Source unavailable','स्रोत उपलब्ध नहीं')]].map(([k,l])=>`<option value="${k}" ${k===c.sourceMode?'selected':''}>${l}</option>`).join('')}</select></details>`:''}<details class="disclosure"><summary>${tr('Manage this check','इस जाँच को सँभालें')}</summary><div class="actions"><button class="btn small" id="export">${tr('Export selected evidence','चुने सबूत निर्यात करें')}</button><button class="btn small danger" id="deleteCase">${tr('Delete case','मामला हटाएँ')}</button></div></details></section>`}
function identityPanel(a,c){return `<div class="checks">${a.checks.map((q,i)=>`<div class="check"><div class="num">${i+1} / 5</div><h3>${word(q.id)}</h3><span class="tag ${q.state}">${word(q.state)}</span><p>${q.detail===q.id?(q.id==='association'?tr('Independent evidence of sender association is still needed.','भेजने वाले के संबंध का स्वतंत्र सबूत चाहिए।'):q.id==='offer'?tr('The exact offer has not been independently confirmed.','इस प्रस्ताव की स्वतंत्र पुष्टि नहीं हुई है।'):tr('Recipient and payment purpose have not been verified.','भुगतान पाने वाले और उद्देश्य की जाँच नहीं हुई है।')):word(q.detail)}</p>${q.value?`<code>${esc(q.value)}</code>`:''}<details class="sourceDetails"><summary>${tr('Source and limits','स्रोत और सीमाएँ')}</summary><small>${tr('Checked','जाँच समय')}: ${date(q.checkedAt)}</small><small>${q.source==='fixture'?tr('Source: sample registry v1','स्रोत: नमूना रजिस्ट्री v1'):tr('Source: unavailable. Official manual check needed.','स्रोत: उपलब्ध नहीं। आधिकारिक जाँच ज़रूरी।')}</small>${q.source==='fixture'?`<small>${tr('Reference date','संदर्भ तारीख')}: ${date(q.sourceDate)}</small>`:''}${c.sourceMode!=='available'?`<small>${tr('Source state','स्रोत स्थिति')}: ${c.sourceMode==='stale'?tr('Stale, not used as verification','पुराना, पुष्टि में उपयोग नहीं'):tr('Unavailable','उपलब्ध नहीं')}</small>`:''}</details></div>`).join('')}</div><div class="notice blue">${tr('Registration, exact name, sender association and exact offer are separate identity checks. Payment is an additional check. None guarantees safety.','पंजीकरण, सही नाम, भेजने वाले का संबंध और यह विशेष प्रस्ताव अलग पहचान जाँच हैं। भुगतान अतिरिक्त जाँच है। कोई भी सुरक्षा की गारंटी नहीं देता।')}</div>`}
function evidencePanel(a,c){return `<div class="paper"><h2>${tr('Why this result appeared','यह परिणाम क्यों आया')}</h2>${a.findings.length?a.findings.map(f=>`<div class="finding"><h3>${esc(f.label)}</h3><blockquote>${esc(f.excerpt)}</blockquote><p class="hint">${tr('Rule','नियम')}: ${f.rule} · ${f.version}<br>${tr('Source','स्रोत')}: ${tr('User-selected message','उपयोगकर्ता का चुना संदेश')} · ${date(c.events.find(e=>e.id===f.eventId).createdAt)}<br>${tr('Limit: a rule match is a concern, not proof of fraud.','सीमा: नियम का मिलना चिंता का संकेत है, धोखाधड़ी का प्रमाण नहीं।')}</p></div>`).join(''):`<p>${tr('No warning rule matched. This does not prove that the sender or offer is genuine.','कोई चेतावनी नियम नहीं मिला। इससे भेजने वाला या प्रस्ताव असली साबित नहीं होता।')}</p>`}<details><summary>${tr('Extracted claims and their exact evidence','निकाले गए दावे और उनके सही सबूत')}</summary>${a.claims.map(q=>`<p><b>${esc(q.type)}</b>: ${esc(q.value)}<br><small class="muted">${tr('Sender claim, not verified fact','भेजने वाले का दावा, सत्यापित तथ्य नहीं')} · ${q.start}–${q.end}</small></p>`).join('')||`<p>${tr('No identity claims extracted.','पहचान के दावे नहीं मिले।')}</p>`}</details></div>`}
function timelinePanel(a,c){return `<div class="paper"><h2>${tr('Evidence timeline','सबूत का क्रम')}</h2><p class="muted">${tr('Only supplied events appear here. No deposit or completed payment is inferred.','यहाँ केवल दिए गए घटनाक्रम हैं। जमा या पूरा भुगतान मान नहीं लिया जाता।')}</p><div class="timeline">${c.events.map((e,i)=>`<article class="event"><h3>${tr('Evidence item','सबूत')} ${i+1}</h3><div class="meta">${date(e.createdAt)} · ${e.synthetic?tr('Demo','नमूना'):tr('Supplied input','दिया गया इनपुट')} · ${e.basis==='user-confirmed'?tr('Linked by you','आपने जोड़ा'):e.basis==='identifier'?tr('Shared exact identifier','समान सही पहचानकर्ता'):tr('Observed input','दिया गया पाठ')}</div><blockquote>${esc(e.text)}</blockquote><div class="actions"><button class="btn small" data-edit="${e.id}">${tr('Correct text','पाठ सुधारें')}</button>${c.events.length>1?`<button class="btn small" data-unlink="${e.id}">${tr('Unlink into new case','अलग मामला बनाएँ')}</button>`:''}<button class="textbtn" data-remove="${e.id}">${tr('Remove item','यह सबूत हटाएँ')}</button></div>${e.corrections.length?`<p class="hint">${e.corrections.length} ${tr('correction(s) recorded. Previous sensitive text is not retained.','सुधार दर्ज। पुराना संवेदनशील पाठ नहीं रखा गया।')}</p>`:''}</article>`).join('')}</div><details><summary>${tr('Stages supported by the supplied evidence','दिए सबूत से समर्थित चरण')}</summary><p>${a.stages.length?a.stages.map(word).join(' / '):tr('No journey stage inferred.','कोई चरण नहीं माना गया।')}</p></details></div>`}
function nextPanel(a,c){return `<div class="paper"><h2>${tr('Pause and verify independently','रुकें और स्वतंत्र जाँच करें')}</h2><div class="steps">${[tr('Keep this payment pending while you check the identity and demand.','पहचान और माँग की जाँच तक यह भुगतान रोक कर रखें।'),tr('Use official sources to confirm the exact registration, category, website and handle.','आधिकारिक स्रोत से सही पंजीकरण, श्रेणी, वेबसाइट और हैंडल जाँचें।'),tr('Find a contact independently. Ask whether this sender, exact offer and payment recipient are authorised.','संपर्क स्वतंत्र स्रोत से लें। पूछें कि भेजने वाला, यह प्रस्ताव और भुगतान पाने वाला अधिकृत हैं या नहीं।')].map((p,i)=>`<div class="step"><span class="num">${i+1}</span><p>${p}</p></div>`).join('')}</div><div class="actions">${external(SOURCES.support,tr('SEBI official resources','SEBI आधिकारिक संसाधन'))}${external(SOURCES.payment,tr('SEBI Check: payment identifiers','SEBI Check: भुगतान पहचानकर्ता'))}</div><p class="hint">${tr('External pages open only when you choose. No message is sent to these sites. Official-source response times and coverage vary.','बाहरी पृष्ठ आपके चुनने पर खुलेंगे। आपका संदेश इन साइटों पर नहीं भेजा जाता। स्रोत की उपलब्धता और समय अलग हो सकते हैं।')}</p><label for="response">${tr('Record what the entity told you (optional)','संस्था ने क्या बताया, दर्ज करें (वैकल्पिक)')}</label><textarea id="response" maxlength="1000" class="compact">${esc(c.response??'')}</textarea><button id="saveResponse" class="btn small">${tr('Save as user-reported response','उपयोगकर्ता द्वारा बताई प्रतिक्रिया सहेजें')}</button><p class="hint">${tr('Your report never automatically verifies a sender or offer.','आपकी प्रतिक्रिया भेजने वाले या प्रस्ताव को अपने आप सत्यापित नहीं करती।')}</p><label class="toggle"><input id="paid" type="checkbox" ${c.paid?'checked':''}><span>${tr('I already sent money','मैं पैसे भेज चुका/चुकी हूँ')}</span></label>${c.paid?`<div class="notice red"><p>${tr('Contact your bank promptly and use the official cybercrime reporting portal. This app does not submit a report or promise recovery.','अपने बैंक से तुरंत संपर्क करें और आधिकारिक साइबर अपराध पोर्टल उपयोग करें। ऐप शिकायत दर्ज या पैसे वापसी का वादा नहीं करता।')}</p>${external(SOURCES.report,tr('Official reporting portal','आधिकारिक शिकायत पोर्टल'))}</div>`:''}</div>`}
function settingsView(){return `<section>${headings(tr('Your data, your choices','आपका डेटा, आपकी पसंद'),tr('Core checks stay on your device. No cloud AI or message upload is connected.','मुख्य जाँच इसी डिवाइस पर होती है। क्लाउड AI या संदेश अपलोड जुड़ा नहीं है।'))}<div class="layout"><div class="paper"><button class="btn small" id="settingsLanguage">${tr('Switch to हिन्दी','Switch to English')}</button><h2 class="spacing">${tr('Storage and retention','संग्रह और अवधि')}</h2><div class="toggle"><input type="checkbox" id="saveLocal" ${state.save?'checked':''}><label for="saveLocal">${tr('Remember cases on this browser','इस ब्राउज़र में मामले याद रखें')}<small>${tr('Off by default. If enabled, an encrypted browser vault stores redacted case text. Otherwise cases disappear when this tab closes.','डिफ़ॉल्ट में बंद। चालू करने पर हटाए गए संवेदनशील पाठ वाले मामले एन्क्रिप्टेड ब्राउज़र संग्रह में रहेंगे। अन्यथा टैब बंद होने पर मामले चले जाएँगे।')}</small></label></div><label for="retention">${tr('Delete saved cases after inactivity','निष्क्रिय मामलों को हटाने की अवधि')}</label><select id="retention"><option value="1" ${state.retention===1?'selected':''}>${tr('1 day','1 दिन')}</option><option value="7" ${state.retention===7?'selected':''}>${tr('7 days','7 दिन')}</option><option value="30" ${state.retention===30?'selected':''}>${tr('30 days','30 दिन')}</option></select><p class="hint">${tr('Expiry runs when the app is open. Browser encryption does not protect against someone with access to this browser or a compromised device. Exported files are outside the app’s deletion controls.','अवधि की जाँच ऐप खुलने पर होती है। ब्राउज़र तक पहुँच रखने वाले या असुरक्षित डिवाइस से एन्क्रिप्शन पूरी सुरक्षा नहीं देता। निर्यात फाइल ऐप से नहीं हटती।')}</p><div class="toggle"><input id="pause" type="checkbox" ${state.paused?'checked':''}><label for="pause">${tr('Pause new analysis','नई जाँच रोकें')}</label></div><button class="btn small" id="clearModel">${tr("Remove downloaded AI model", "डाउनलोड किया AI मॉडल हटाएँ")}</button><button class="btn danger" id="deleteAll">${tr('Delete all cases and browser vault','सभी मामले और ब्राउज़र संग्रह हटाएँ')}</button><details><summary>${tr('Privacy boundaries','गोपनीयता की सीमाएँ')}</summary><p>${tr('No app analytics, remote case database or cloud text analysis. Optional ML downloads public model files from Hugging Face; the text is processed locally. Voice recognition may send audio to the browser speech provider. Clerk processes account authentication over the network. Case content is not sent to Clerk. We redact common sensitive patterns, but unusual secrets can be missed. Review your text before checking. Saved cases are separated by account within this browser; there is no cloud sync. Authentication is managed separately by Clerk.','ऐप एनालिटिक्स या क्लाउड पाठ जाँच नहीं है। वैकल्पिक ML की मॉडल फाइलें Hugging Face से आती हैं; संदेश इसी ब्राउज़र में प्रोसेस होता है। आवाज़ की पहचान ब्राउज़र प्रदाता को ऑडियो भेज सकती है। Clerk नेटवर्क पर खाता प्रमाणीकरण करता है। मामले Clerk को नहीं भेजे जाते। सामान्य संवेदनशील पैटर्न हटते हैं, लेकिन जानकारी छूट सकती है। मामले इसी ब्राउज़र में खाते के अनुसार अलग हैं; क्लाउड सिंक नहीं है।')}</p></details></div><aside class="paper"><h2>${tr('Capture capabilities','इनपुट क्षमताएँ')}</h2><p>${tr('Working here: paste messages and links, review selected screenshot text and replay labelled samples.','यहाँ काम करता है: संदेश और लिंक पेस्ट करना, चुने स्क्रीनशॉट का पाठ देखना और नमूने चलाना।')}</p><p class="notice">${tr('This web app checks only what you choose to paste or select. It cannot read your WhatsApp or Telegram notifications or private chats.','यह वेब ऐप केवल आपका चुना या पेस्ट किया हुआ पाठ जाँचता है। यह WhatsApp या Telegram की सूचनाएँ या निजी चैट नहीं पढ़ सकता।')}</p><p>${tr('Hindi/English screenshot text is read locally. Speech depends on browser support. Public HTTPS links are retrieved by our server.','हिन्दी/अंग्रेज़ी स्क्रीनशॉट का पाठ इसी डिवाइस पर पढ़ा जाता है। आवाज़ ब्राउज़र पर निर्भर है। सार्वजनिक HTTPS लिंक सर्वर से पढ़े जाते हैं।')}</p><p>${tr('Voice requires your explicit start action and microphone permission. ML files are cached separately from cases. No cloud text-analysis provider is connected.','आवाज़ के लिए आपका स्पष्ट चुनाव और माइक्रोफ़ोन अनुमति चाहिए। ML मॉडल फाइलें मामलों से अलग कैश होती हैं। क्लाउड पाठ जाँच जुड़ी नहीं है।')}</p></aside></div></section>`}
function openContact(){const c=state.cases.find(c=>c.id===state.selected),a=result(c);const fixture=a.fixtureUsed;modal(tr('Independent contact check','स्वतंत्र संपर्क जाँच'),`<p class="notice ${fixture?'blue':''}">${fixture?tr('DEMO CONTACT ONLY · This .example address is fictional. Do not contact it.','केवल नमूना संपर्क · यह .example पता काल्पनिक है। संपर्क न करें।'):tr('Verification incomplete. No independently sourced entity contact is available here.','जाँच अधूरी है। संस्था का स्वतंत्र स्रोत वाला संपर्क यहाँ उपलब्ध नहीं है।')}</p>${fixture?`<p><b>${FIXTURE.name}</b><br><code>${FIXTURE.contact}</code></p><p class="hint">${tr('Source: synthetic fixture v1','स्रोत: काल्पनिक नमूना v1')}<br>${tr('Reference date','संदर्भ तारीख')}: ${date(FIXTURE.date)}<br>${tr('Lookup time','जाँच समय')}: ${date(new Date().toISOString())}<br>${tr('No real contact or official authentication.','वास्तविक संपर्क या आधिकारिक प्रमाणीकरण नहीं।')}</p>`:''}<p>${tr('Use the official registry to establish the entity’s website and contact independently. Never use the suspicious message’s own contact as proof.','संस्था की वेबसाइट और संपर्क स्वतंत्र रूप से पाने के लिए आधिकारिक रजिस्ट्री उपयोग करें। संदिग्ध संदेश के संपर्क को प्रमाण न मानें।')}</p>${external(SOURCES.support,tr('Open official verification resources','आधिकारिक जाँच संसाधन खोलें'))}<h3 class="spacing">${tr('Questions to ask','पूछने वाले सवाल')}</h3><ol><li>${tr('Does this sender and domain represent your entity?','क्या यह भेजने वाला और वेबसाइट आपकी संस्था के हैं?')}</li><li>${tr('Did you issue this exact offer?','क्या आपने यह विशेष प्रस्ताव दिया है?')}</li><li>${tr('Is this recipient and payment purpose authorised?','क्या भुगतान पाने वाला और भुगतान का उद्देश्य अधिकृत हैं?')}</li></ol><p class="hint">${tr('A contact or registration match does not authenticate the offer. You choose whether to make contact.','संपर्क या पंजीकरण मिलना प्रस्ताव को सत्यापित नहीं करता। संपर्क करना आपका फैसला है।')}</p>`)}
function selected(){return state.cases.find(c=>c.id===state.selected)}
function nativeSettings(){
 let cap;try{cap=JSON.parse(native.capabilities())}catch{return}
 const box=document.createElement('div');box.className='paper';box.innerHTML=`<h2>${tr('Android selected notifications','Android चुनी सूचनाएँ')}</h2><p class="notice">${tr('Permission','अनुमति')}: ${cap.access?tr('Granted','दी गई'):tr('Not granted','नहीं दी गई')} · ${cap.connected?tr('Listener connected','इनपुट जुड़ा है'):tr('Listener disconnected','इनपुट नहीं जुड़ा')} · ${cap.paused?tr('Paused','रुका'):tr('Active','सक्रिय')}</p><p>${tr('Android grants broad notification access. These selected-app filters are our own controls. Missing or redacted previews cannot be recovered.','Android व्यापक सूचना अनुमति देता है। चुने ऐप का फ़िल्टर हमारा नियंत्रण है। छिपा या हटाया गया पाठ नहीं पढ़ा जा सकता।')}</p><label class="toggle"><input id="nativeWa" type="checkbox" ${cap.allowed.includes('com.whatsapp')?'checked':''}><span>WhatsApp</span></label><label class="toggle"><input id="nativeTg" type="checkbox" ${cap.allowed.includes('org.telegram.messenger')?'checked':''}><span>Telegram</span></label><label class="toggle"><input id="nativePause" type="checkbox" ${cap.paused?'checked':''}><span>${tr('Pause native capture','Android इनपुट रोकें')}</span></label><div class="actions"><button id="nativeConfigure" class="btn">${tr('Save capture choices','इनपुट विकल्प सहेजें')}</button><button id="nativePermission" class="btn">${tr('Manage Android access','Android अनुमति बदलें')}</button><button id="nativeImport" class="btn primary">${tr('Review captured items','आए हुए संदेश देखें')} (${cap.queueCount})</button></div><p class="hint">${tr('Preview status','पाठ स्थिति')}: ${esc(cap.capture)}<br>${tr('Capture queue is encrypted with an Android Keystore key. It expires after seven days when accessed. Imported cases use the browser storage choices above.','इनपुट कतार Android Keystore कुंजी से एन्क्रिप्टेड है। पढ़ने पर सात दिन पुराने संदेश हटते हैं। आयातित मामले ऊपर के संग्रह विकल्प उपयोग करते हैं।')}</p><label class="toggle"><input id="nativeAlerts" type="checkbox" ${cap.alerts?'checked':''}><span>${tr('Allow generic concern alerts (separate permission)','सामान्य चेतावनी सूचना चालू करें (अलग अनुमति)')}</span></label><button id="nativeClear" class="textbtn">${tr('Delete native capture queue','Android इनपुट कतार हटाएँ')}</button>`;
 $('#main .layout>div').append(box);
 $('#nativeConfigure').onclick=()=>{native.configure($('#nativeWa').checked,$('#nativeTg').checked,$('#nativePause').checked);render()};$('#nativePermission').onclick=()=>native.requestAccess();
 $('#nativeImport').onclick=()=>{let rows;try{rows=JSON.parse(native.inbox())}catch{rows=[]}modal(tr('Review captured investment previews','आए निवेश संदेश देखें'),rows.length?rows.map((r,i)=>`<div class="finding"><h3>${esc(r.app)}</h3><blockquote>${esc(r.text)}</blockquote><button class="btn small" data-import-native="${i}">${tr('Create separate case','अलग मामला बनाएँ')}</button></div>`).join(''):`<p>${tr('No readable selected investment preview is available. Share or paste a message instead.','चुना निवेश संदेश उपलब्ध नहीं है। संदेश शेयर या पेस्ट करें।')}</p>`,()=>{$$('[data-import-native]').forEach(b=>b.onclick=async()=>{const r=rows[Number(b.dataset.importNative)];if(state.cases.some(c=>c.events.some(e=>e.originalId===r.id))){toast('Already imported.','पहले से आयात किया गया।');return}try{const e=makeEvent(r.text,{source:'android-notification',originalId:r.id,now:new Date(r.time).toISOString()});state.cases.unshift({id:crypto.randomUUID(),events:[e],fixture:false,sourceMode:'unavailable',synthetic:false,createdAt:e.createdAt,updatedAt:new Date().toISOString(),response:'',paid:false});await persist();toast('Created a separate case. No automatic linking.','अलग मामला बना। अपने आप नहीं जोड़ा गया।')}catch{toast('This preview has insufficient investment context.','इस संदेश में निवेश का पर्याप्त संदर्भ नहीं है।')}})})};
 $('#nativeAlerts').onchange=e=>native.setAlerts(e.target.checked);
 $('#nativeClear').onclick=()=>confirmAction(tr('Delete native queued previews?','Android कतार के संदेश हटाएँ?'),tr('The queued excerpts and encryption key will be removed.','कतार के पाठ और एन्क्रिप्शन कुंजी हटेंगे।'),()=>{native.clearCapture();render()});
}
async function addEvent(c,text,opts={}){if(state.paused)throw Error('paused');const e=makeEvent(text,opts);if(c.events.some(x=>x.text===e.text)){toast('This evidence is already in the case.','यह सबूत मामले में पहले से है।');return false}if(c.events.length>=50)throw Error('limit');c.events.push(e);c.synthetic=c.events.every(e=>e.synthetic);if(!c.synthetic)c.fixture=false;c.updatedAt=new Date().toISOString();await persist();return true}
function editModal(event){const c=selected();modal(event?tr('Correct the evidence','सबूत सुधारें'):tr('Add related evidence','जुड़ा सबूत जोड़ें'),`<label for="eventText">${tr('Message or link','संदेश या लिंक')}</label><textarea id="eventText" maxlength="10000">${esc(event?.text??'')}</textarea>${!event?`<label class="toggle"><input type="checkbox" id="confirmLink"><span>${tr('I confirm this belongs to the same conversation or offer.','मैं पुष्टि करता/करती हूँ कि यह उसी बातचीत या प्रस्ताव का हिस्सा है।')}</span></label>`:''}<p class="hint">${tr('Sensitive patterns are removed. A common name alone does not link cases.','संवेदनशील पैटर्न हटेंगे। केवल समान नाम से मामले नहीं जुड़ते।')}</p><div id="eventError" class="error" role="alert"></div><button id="eventSave" class="btn primary">${tr('Save evidence','सबूत सहेजें')}</button>`,()=>{$('#eventSave').onclick=async()=>{try{const text=$('#eventText').value;if(event){const e=makeEvent(text,{id:event.id,source:event.source,now:event.createdAt,basis:'user-confirmed'});e.corrections=[...event.corrections,{at:new Date().toISOString(),method:'user correction'}];c.events[c.events.indexOf(event)]=e;c.fixture=false;c.synthetic=false;c.updatedAt=new Date().toISOString();await persist()}else{if(!$('#confirmLink').checked&&!canLink(c.events,text))throw Error('link');await addEvent(c,text,{basis:$('#confirmLink').checked?'user-confirmed':'identifier'})}$('#modal').close();state.tab='timeline';state.detailsOpen=true;render()}catch(e){$('#eventError').textContent=e.message==='link'?tr('Confirm the relationship, or create a separate case.','संबंध की पुष्टि करें या अलग मामला बनाएँ।'):tr('Use a relevant investment message with readable text.','पढ़ने योग्य निवेश संबंधी संदेश दें।')}}})}
function exportCheck(c,ids){const events=c.events.filter(e=>ids.includes(e.id));const {score,...checks}=analyze(events,{fixture:c.fixture,sourceMode:c.sourceMode,lang:state.lang});return {...checks,score:displayedScore(scoreState(events.map(e=>e.text).join('\n')),score)}}
function exportModal(){const c=selected();modal(tr('Choose evidence to export','निर्यात के लिए सबूत चुनें'),`<p>${tr('Exported files contain your selected redacted text. Keep them private.','फाइल में आपका चुना हुआ पाठ होगा। इसे निजी रखें।')}</p>${c.events.map((e,i)=>`<label class="toggle"><input type="checkbox" name="exportEvent" value="${e.id}" checked><span>${tr('Item','सबूत')} ${i+1}</span></label>`).join('')}<button class="btn primary" id="download">${tr('Download JSON','JSON डाउनलोड करें')}</button>`,()=>{$('#download').onclick=()=>{const ids=$$('#modal input:checked').map(i=>i.value);const blob=new Blob([JSON.stringify({schema:1,rules:VERSION,exportedAt:new Date().toISOString(),synthetic:c.synthetic,events:c.events.filter(e=>ids.includes(e.id)),result:exportCheck(c,ids),notice:'Limited evidence, not proof of investment safety.'},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='nivesh-rakshak-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#modal').close()}})}
function speak(){if(!window.speechSynthesis){toast('Speech is unavailable. Read the displayed explanation.','आवाज़ उपलब्ध नहीं। दिखाया गया पाठ पढ़ें।');return}if(speechSynthesis.speaking){speechSynthesis.cancel();$('#listen').textContent=tr('Listen to the result','परिणाम सुनें');return}const a=result(selected()),lang=state.lang==='hi'?'hi-IN':'en-IN';const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith(state.lang));const u=new SpeechSynthesisUtterance(($('#primaryResult')?.innerText||word(a.band))+'. '+tr('Message concern score ','संदेश का चिंता स्कोर ')+(displayedScore(scoreState(caseText(selected())),a.score).value??tr('unavailable','उपलब्ध नहीं'))+(scoreState(caseText(selected())).status==='error'?tr('. Rules-based fallback, not AI. ', '। नियम आधारित जाँच, AI नहीं। '):tr('. Model-derived signal. ','। मॉडल से मिला संकेत। '))+tr('Not a fraud probability. ','धोखाधड़ी की संभावना नहीं। ')+a.findings.map(f=>f.label).join('. ')+'. '+tr('Live official verification is pending. Verify through an independent official contact before paying.','लाइव आधिकारिक जाँच बाकी है। भुगतान से पहले स्वतंत्र आधिकारिक संपर्क से पुष्टि करें।'));if(voice)u.voice=voice;u.lang=voice?.lang||lang;u.rate=.9;const btn=$('#listen');btn.textContent=tr('Stop reading','पढ़ना बंद करें');u.onend=()=>{if(btn.isConnected)btn.textContent=tr('Listen to the result','परिणाम सुनें')};u.onerror=()=>{u.onend();toast('Speech could not play. The complete result is on screen.','आवाज़ नहीं चल सकी। पूरा परिणाम स्क्रीन पर है।')};speechSynthesis.speak(u)}

let captureId=0;
async function screenshot(file){
 if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choose a PNG, JPEG or WebP under 5 MB.','5 MB से छोटी PNG, JPEG या WebP चुनें।');return;}
 const id=++captureId,box=$('#input'),button=$('#analyze'),error=$('#inputError');state.input='';box.value='';button.disabled=true;box.readOnly=true;
 const u=URL.createObjectURL(file),img=new Image();img.className='previewimg';img.alt='Selected screenshot';img.src=u;$('#imagePreview').replaceChildren(img);
 try{await img.decode();if(img.naturalWidth*img.naturalHeight>24000000)throw Error('Choose a smaller screenshot.');const {readScreenshot}=await import('./ocr.mjs');const text=await readScreenshot(file,p=>{if(error.isConnected)error.textContent=tr('Reading screenshot… ','स्क्रीनशॉट पढ़ रहे हैं… ')+Math.round(p*100)+'%';});if(id!==captureId||!box.isConnected)return;box.value=text;state.input=text;state.synthetic=false;state.fixture=false;error.textContent=tr('Text extracted. Click Check this offer—no typing needed.','पाठ मिल गया। यह प्रस्ताव जाँचें दबाएँ—लिखने की ज़रूरत नहीं।');}
 catch{if(error.isConnected)error.textContent=tr('Could not read this screenshot. Try a clearer image with visible text.','स्क्रीनशॉट नहीं पढ़ सके। स्पष्ट पाठ वाली तस्वीर चुनें।');}
 finally{URL.revokeObjectURL(u);if(box.isConnected){box.readOnly=false;button.disabled=state.paused;}}
}

function bind(){
 if($('#clearModel'))$('#clearModel').onclick=async()=>{clearML();try{if('caches' in window)await caches.delete('transformers-cache');toast('Cached AI model removed. A future AI check will download it again.','कैश किया AI मॉडल हटा। अगली AI जाँच में फिर डाउनलोड होगा।')}catch{toast('Model cache could not be cleared. Use your browser site-data settings.','मॉडल कैश नहीं हटा। ब्राउज़र की साइट-डेटा सेटिंग उपयोग करें।')}};

 if($('#mlPanel')){const c=selected();mountML({host:$('#mlPanel'),text:c.events.map(e=>e.text).join("\n"),lang:state.lang,claims:result(c).claims,disabled:state.paused,onState:info=>{analysisStates.set(caseText(c),info);if(state.selected===c.id&&$('#modelScorePanel')){$('#modelScorePanel').innerHTML=scoreMarkup(info);updatePrimary(info,c);}}});}

 if($('#voiceStart'))$('#voiceStart').onclick=()=>{
  if(voiceInput?.active){voiceInput.stop();return;}
  const status=$('#voiceStatus'),input=$('#input'),mic=$('#voiceStart'),langSelect=$('#voiceLanguage'),hint=$('#voiceHint'),analyzeButton=$('#analyze');
  const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Recognition){status.textContent=tr('Voice typing is not supported here. Open this page in Google Chrome, or use your phone keyboard’s microphone.','यहाँ बोलकर लिखना उपलब्ध नहीं है। पेज Google Chrome में खोलें या फोन के कीबोर्ड का माइक इस्तेमाल करें।');return;}
  if(state.paused){status.textContent=tr('Resume checks in Settings before using the microphone.','माइक इस्तेमाल करने से पहले सेटिंग्स में जाँच चालू करें।');return;}
  window.speechSynthesis?.cancel();
  const base=input.value;
  const labels={starting:tr('Allow microphone access if asked…','अनुमति माँगी जाए तो माइक की अनुमति दें…'),listening:tr('Listening… Your words appear in the box. Tap the red button to stop.','सुन रहे हैं… आपके शब्द बॉक्स में दिखेंगे। रोकने के लिए लाल बटन दबाएँ।'),stopping:tr('Finishing your sentence…','आपका वाक्य पूरा हो रहा है…'),review:tr('Microphone off. Check the text—you can edit it now.','माइक बंद है। पाठ देखें—अब आप इसे सुधार सकते हैं।'),denied:tr('Microphone access is blocked. Allow Microphone in this site’s browser permissions, then tap the mic again.','माइक की अनुमति बंद है। ब्राउज़र की साइट अनुमति में Microphone चालू करें, फिर माइक दबाएँ।'),'no-speech':tr('No speech heard. Check your microphone and try again.','आवाज़ नहीं मिली। माइक जाँचें और फिर कोशिश करें।'),microphone:tr('No working microphone found. Connect a microphone or use keyboard dictation.','काम करता माइक नहीं मिला। माइक जोड़ें या कीबोर्ड से बोलकर लिखें।'),network:tr('The browser’s speech service could not connect. Check your internet or try Google Chrome. Your text is kept.','ब्राउज़र की वॉइस सेवा जुड़ नहीं सकी। इंटरनेट जाँचें या Google Chrome में कोशिश करें। आपका पाठ सुरक्षित है।'),language:tr('This speaking language is not available in your browser. Choose another language or type instead.','ब्राउज़र में यह बोलने की भाषा उपलब्ध नहीं है। दूसरी भाषा चुनें या लिखें।'),'start-timeout':tr('The microphone did not start. Check site microphone permissions, or open this page in Google Chrome.','माइक शुरू नहीं हुआ। साइट की माइक अनुमति जाँचें या पेज Google Chrome में खोलें।'),error:tr('Voice typing could not start. Try Google Chrome or your keyboard’s microphone. Your text is kept.','बोलकर लिखना शुरू नहीं हुआ। Google Chrome या कीबोर्ड का माइक इस्तेमाल करें। आपका पाठ सुरक्षित है।')};
  voiceInput=createVoiceInput({Recognition,lang:langSelect.value,
   onText:(final,interim)=>{input.value=dictationText(base,final,interim);input.dispatchEvent(new Event('input'));input.scrollTop=input.scrollHeight;},
   onStatus:key=>{status.textContent=labels[key]||labels.error;const live=['starting','listening','stopping'].includes(key);mic.classList.toggle('listening',live);mic.classList.toggle('waiting',key==='starting'||key==='stopping');mic.innerHTML=live?stopIcon:micIcon;mic.setAttribute('aria-pressed',String(live));const label=live?tr('Stop voice typing','बोलकर लिखना रोकें'):tr('Start voice typing','बोलकर लिखना शुरू करें');mic.setAttribute('aria-label',label);mic.title=label;mic.disabled=key==='stopping';langSelect.disabled=live;input.readOnly=live;analyzeButton.disabled=live||state.paused;hint.textContent=live?tr('Listening · tap to stop','सुन रहे हैं · रोकने के लिए दबाएँ'):tr('Type or tap the microphone','लिखें या माइक दबाएँ');}
  });voiceInput.start();
 };

 if($('#settingsLanguage'))$('#settingsLanguage').onclick=()=>$('#language').click();
 if($('#bookmarkCase'))$('#bookmarkCase').onclick=async()=>{selected().bookmarked=!selected().bookmarked;await persist();render();toast(state.save?'Saved list updated.':'Saved list updated for this session. Enable browser storage in Settings to keep it after closing.',state.save?'सहेजी सूची बदली।':'इस सत्र की सूची बदली। बाद में रखने के लिए सेटिंग्स में संग्रह चालू करें।')};
 if($('#uploadShortcut'))$('#uploadShortcut').onclick=()=>{state.inputType='screenshot';render();$('#image').click()};
 if($('#topLanguage'))$('#topLanguage').onclick=()=>$('#language').click();
 if($('#aboutProfile'))$('#aboutProfile').onclick=()=>{window.Clerk.openUserProfile();};
 if($('#dashboardSearch'))$('#dashboardSearch').onkeydown=e=>{if(e.key==='Enter'){const query=e.target.value;state.view='cases';render();$('#search').value=query;$('#search').dispatchEvent(new Event('input'));$('#search').focus()}};
 $$('[data-guide]').forEach(b=>b.onclick=()=>openGuide(b.dataset.guide));

 if($('#checkDetails'))$('#checkDetails').ontoggle=e=>{state.detailsOpen=e.target.open};
 $$('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$$('[data-input]').forEach(b=>b.onclick=()=>{state.inputType=b.dataset.input;render()});$$('[data-case]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.case;state.view='result';state.tab='identity';state.detailsOpen=false;render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});
 $$('[data-sample]').forEach(b=>b.onclick=()=>{const k=b.dataset.sample;state.input=state.lang==='hi'&&k==='identity'?SAMPLE.hindi:SAMPLE[k];state.inputType='message';state.synthetic=true;state.fixture=true;state.sourceMode=k==='offline'?'unavailable':'available';render();$('#input').focus()});
 if($('#input'))$('#input').oninput=e=>{state.input=e.target.value;state.synthetic=false;state.fixture=false};if($('#image'))$('#image').onchange=e=>screenshot(e.target.files[0]);if($('#clearInput'))$('#clearInput').onclick=()=>{state.input='';state.synthetic=false;render()};
 if($('#analyze'))$('#analyze').onclick=async()=>{try{if(state.paused)return;let content=state.input;let linkMeta;if(state.inputType==='link'){const button=$('#analyze');button.disabled=true;$('#inputError').textContent=tr('Reading linked page…','लिंक का पेज पढ़ रहे हैं…');try{const response=await fetch('/api/read-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:content.trim()}),signal:AbortSignal.timeout(45000)});const data=await response.json();if(!button.isConnected)return;if(!response.ok)throw Error(data.error||'Page unavailable');content=data.url+'\n'+data.text;linkMeta={url:data.url,retrievedAt:data.retrievedAt,partial:data.partial};}catch{throw Error('link-unavailable');}finally{if(button.isConnected)button.disabled=false;}}const e=makeEvent(content,{synthetic:state.synthetic,source:state.inputType});if(linkMeta)e.linkSource=linkMeta;const c={id:crypto.randomUUID(),events:[e],fixture:state.fixture,sourceMode:state.sourceMode,synthetic:e.synthetic,createdAt:e.createdAt,updatedAt:e.createdAt,response:'',paid:false};state.cases.unshift(c);state.selected=c.id;state.input='';state.synthetic=false;state.fixture=false;await persist();state.view='result';state.tab='identity';state.detailsOpen=false;render()}catch(error){if($('#inputError'))$('#inputError').textContent=error.message==='link-unavailable'?tr('This page could not be read. Use a public HTTPS page without query parameters, or upload a screenshot of the offer.','पेज नहीं पढ़ सके। बिना query parameters का सार्वजनिक HTTPS पेज दें या प्रस्ताव का स्क्रीनशॉट अपलोड करें।'):tr('No readable investment content found. Choose a clear screenshot or an investment page.','पढ़ने योग्य निवेश पाठ नहीं मिला। स्पष्ट स्क्रीनशॉट या निवेश पेज चुनें।')}};
 if($('#search'))$('#search').oninput=e=>{const q=e.target.value.toLocaleLowerCase();$('#caseList').innerHTML=visibleCases().filter(c=>c.events.some(e=>e.text.toLocaleLowerCase().includes(q))).map(caseRow).join('')||`<p>${tr('No matching case','मिलता मामला नहीं')}</p>`;$$('[data-case]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.case;state.view='result';render()})};
 if($('#nextStep'))$('#nextStep').onclick=()=>{state.tab='next';render()};if($('#contact'))$('#contact').onclick=openContact;if($('#listen'))$('#listen').onclick=speak;if($('#addEvidence'))$('#addEvidence').onclick=()=>editModal();
 for(const [id,k] of [['samplePortal','portal'],['sampleFee',state.lang==='hi'?'hindiFee':'fee']])if($('#'+id))$('#'+id).onclick=async()=>{await addEvent(selected(),SAMPLE[k],{synthetic:true,basis:'identifier',source:'demo'});state.tab='timeline';state.detailsOpen=true;render()};
 if($('#sourceMode'))$('#sourceMode').onchange=async e=>{selected().sourceMode=e.target.value;await persist();render()};
 $$('[data-edit]').forEach(b=>b.onclick=()=>editModal(selected().events.find(e=>e.id===b.dataset.edit)));
 $$('[data-remove]').forEach(b=>b.onclick=()=>confirmAction(tr('Remove this evidence?','यह सबूत हटाएँ?'),tr('Findings will be recalculated.','परिणाम दोबारा निकाले जाएँगे।'),async()=>{const c=selected();c.events=c.events.filter(e=>e.id!==b.dataset.remove);c.updatedAt=new Date().toISOString();if(!c.events.length){state.cases=state.cases.filter(x=>x!==c);state.view='cases'}await persist();render()}));
 $$('[data-unlink]').forEach(b=>b.onclick=()=>confirmAction(tr('Move into a separate case?','अलग मामले में ले जाएँ?'),tr('This removes the relationship and recalculates both cases.','संबंध हटेगा और दोनों मामले फिर जाँचे जाएँगे।'),async()=>{const c=selected(),e=c.events.find(e=>e.id===b.dataset.unlink);c.events=c.events.filter(x=>x!==e);e.basis='observed';state.cases.unshift({...c,id:crypto.randomUUID(),events:[e],synthetic:e.synthetic,response:'',paid:false,updatedAt:new Date().toISOString()});c.updatedAt=new Date().toISOString();await persist();render()}));
 if($('#deleteCase'))$('#deleteCase').onclick=()=>confirmAction(tr('Delete this case?','यह मामला हटाएँ?'),tr('All its evidence, findings and recorded responses will be removed from this browser.','इस ब्राउज़र से इसके सबूत, परिणाम और प्रतिक्रियाएँ हटेंगे।'),async()=>{clearML();state.cases=state.cases.filter(c=>c.id!==state.selected);state.selected=null;state.view='cases';await persist();render()});if($('#export'))$('#export').onclick=exportModal;
 if($('#saveResponse'))$('#saveResponse').onclick=async()=>{selected().response=redact($('#response').value).text;await persist();toast('Saved as your report, not independent verification.','आपकी प्रतिक्रिया के रूप में संग्रह हुआ, स्वतंत्र पुष्टि नहीं।')};if($('#paid'))$('#paid').onchange=async e=>{selected().paid=e.target.checked;await persist();render()};
 if($('#saveLocal'))$('#saveLocal').onchange=async e=>{if(e.target.checked)confirmAction(tr('Enable encrypted browser storage?','एन्क्रिप्टेड ब्राउज़र संग्रह चालू करें?'),tr('Redacted case text and responses will stay in this browser for the chosen retention period. No server receives them. Anyone with browser access can still open the cases.','चुना हुआ पाठ और प्रतिक्रियाएँ तय अवधि तक इसी ब्राउज़र में रहेंगी। सर्वर को नहीं जाएँगी। ब्राउज़र तक पहुँच वाला व्यक्ति मामले खोल सकता है।'),async()=>{state.save=true;await persist();render()});else{state.save=false;clearML();await clearVault();render()}};
 if($('#retention'))$('#retention').onchange=async e=>{state.retention=Number(e.target.value);prune();await persist();render()};if($('#pause'))$('#pause').onchange=e=>{state.paused=e.target.checked;speechSynthesis?.cancel();toast(state.paused?'Processing paused.':'Processing resumed.',state.paused?'जाँच रुकी।':'जाँच शुरू हुई।')};if($('#deleteAll'))$('#deleteAll').onclick=()=>confirmAction(tr('Delete everything on this browser?','इस ब्राउज़र का सब कुछ हटाएँ?'),tr('Cases, excerpts, responses and the encryption key will be deleted. Downloaded exports remain outside the app.','मामले, पाठ, प्रतिक्रियाएँ और एन्क्रिप्शन कुंजी हटेंगे। डाउनलोड की गई फाइलें ऐप के बाहर रहेंगी।'),async()=>{state.cases=[];state.selected=null;state.save=false;state.input='';clearML();await clearVault();native?.clearCapture();speechSynthesis?.cancel();render()});
}
$('#modal').addEventListener('close',()=>{if($('#saveLocal'))$('#saveLocal').checked=state.save});
$('.brand').onclick=e=>{e.preventDefault();state.view='check';render()};
$('#language').onclick=()=>{state.lang=state.lang==='en'?'hi':'en';localStorage.setItem('nr-language',state.lang);speechSynthesis?.cancel();render()};
$('#coverage').onclick=()=>modal(tr('Prototype coverage','प्रोटोटाइप का दायरा'),`<p>${tr('Working: local text rules, separate identity states, labelled sample registry, timeline, correction, unlink, export, deletion and Hindi / English screens.','काम करता है: स्थानीय पाठ नियम, अलग पहचान स्थिति, नमूना रजिस्ट्री, क्रम, सुधार, अलग करना, निर्यात, हटाना और हिन्दी / अंग्रेज़ी स्क्रीन।')}</p><p>${tr('Live registry / official contact retrieval is not connected. Real inputs remain unverified and receive official manual routes.','लाइव रजिस्ट्री / आधिकारिक संपर्क प्राप्त करना जुड़ा नहीं है। वास्तविक इनपुट की जाँच बाकी रहती है और आधिकारिक रास्ता दिया जाता है।')}</p><p>${tr('Added: optional pretrained multilingual ML / NLP meaning classification, tokenizer diagnostics and Hindi / English voice input. Conditional: browser OCR and speech services. Separate Android project: notification capture and device tests. No deepfake scanner, bank control or dedicated tip-group profiler. Includes a heuristic risk signal score.','शर्त पर: ब्राउज़र OCR और उपलब्ध आवाज़ें। अलग Android परियोजना: सूचना इनपुट और डिवाइस परीक्षण। डीपफेक स्कैनर, बैंक नियंत्रण या विशेष टिप-समूह विश्लेषक नहीं। नियम आधारित जोखिम संकेत स्कोर उपलब्ध है।')}</p><p class="hint">${VERSION} · ${tr('Official resource links reviewed','आधिकारिक लिंक समीक्षा')}: 4 October 2026</p>`);
try{const saved=await loadVault();if(saved?.schema===1&&Array.isArray(saved.cases)){state.cases=saved.cases;state.retention=[1,7,30].includes(saved.settings?.retention)?saved.settings.retention:7;state.save=true;prune();await persist()}}catch{toast('Browser vault unavailable. Session mode remains available.','ब्राउज़र संग्रह उपलब्ध नहीं। सत्र मोड उपयोग कर सकते हैं।')}
if(native){try{const shared=native.sharedText();if(shared)state.input=redact(shared).text}catch{}}
render();setInterval(()=>{const n=state.cases.length;prune();if(n!==state.cases.length){persist();render()}},60000);
